dashboard.definition:
{
    "visualizations": {
        "viz_iot": {
            "type": "splunk.custom",
            "options": {
                "type": "better_map",
                "name": "better_map",
                "tileProvider": "openfreemap-positron",
                "pointRenderer": "hexbin",
                "hexbinAutoDegrade": "true",
                "hexbinAggregate": "mean",
                "enable3DExtrusion": "true",
                "extrusionScale": "120",
                "palette": "viridis"
            },
            "dataSources": {
                "primary": "ds_iot"
            }
        }
    },
    "dataSources": {
        "ds_iot": {
            "type": "ds.search",
            "options": {
                "query": "| makeresults count=2500 | streamstats c | eval lat = 47 + (random()%1000)/200.0 | eval lon = 8 + (random()%1000)/200.0 | eval value = round(15 + random()%65 + 10*sin(c/12.0), 2) | fields lat lon value"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": { "earliest": "-15m", "latest": "now" }
                }
            }
        }
    },
    "inputs": {},
    "layout": {
        "type": "absolute",
        "options": { "width": 1440, "height": 960, "backgroundColor": "#0b1a2d" },
        "structure": [
            { "item": "viz_iot", "type": "block", "position": { "x": 0, "y": 0, "w": 1440, "h": 960 } }
        ]
    }
}
